package com.exito.chop;
import android.net.Uri;import java.io.*;import java.util.concurrent.atomic.AtomicInteger;
final class Drums {
 final Engine engine;final AtomicInteger version=new AtomicInteger();volatile boolean playing;volatile int bpm=90,originalBpm=90,rate=44100;volatile float volume=.55f;volatile String name="Boom bap · 90 BPM";volatile short[] pcm,rendered;
 Drums(Engine e){engine=e;}
 void importLoop(Uri uri){load(uri,null);}void loadSaved(File file){load(Uri.fromFile(file),file);}
 void load(Uri uri,File stored){if(engine.busy)return;engine.history.begin("Cargar loop de drums");stop();engine.busy=true;engine.message("Cargando drums…");engine.worker.execute(()->{try{AudioFiles.Sample s=AudioFiles.decode(engine.context,uri);int original=Analysis.estimate(s.pcm,s.rate)[0];if(stored!=null){File meta=new File(stored.getAbsolutePath()+".bpm");if(meta.exists())try(BufferedReader in=new BufferedReader(new FileReader(meta))){original=Math.max(30,Math.min(300,Integer.parseInt(in.readLine())));}}short[] ready=Dsp.stretch(s.pcm,s.rate,Math.max(.25f,Math.min(4,bpm/(float)original)),1);pcm=s.pcm;rate=s.rate;name=s.name;originalBpm=original;rendered=ready;engine.busy=false;engine.history.end();engine.message("Drums preparados · corrige su BPM original si hace falta");}catch(Throwable error){engine.busy=false;engine.history.cancel();engine.message("Drums: "+Engine.reason(error));}});}
 void demo(){preset(0);}void preset(int style){if(engine.busy)return;engine.history.begin("Loop integrado");stop();pcm=Dsp.drums(44100,style);rendered=null;rate=44100;originalBpm=90;bpm=engine.slots.masterBpm;name=new String[]{"Boom bap","Break","House"}[style]+" · original integrado";engine.history.end();engine.changed();}
 File directory(){File f=new File(engine.context.getFilesDir(),"drums");f.mkdirs();return f;}
 void save(String title){if(pcm==null)return;final short[] data=pcm;final int sr=rate,original=originalBpm;String clean=title.replaceAll("[^\\p{L}\\p{N} _-]","").trim();if(clean.isEmpty())clean="Mi loop";File f=new File(directory(),clean+".wav");engine.worker.execute(()->{try(OutputStream out=new FileOutputStream(f)){AudioFiles.writeWav(out,data,sr);try(Writer writer=new FileWriter(f.getAbsolutePath()+".bpm")){writer.write(""+original);}engine.message("Drums guardados: "+f.getName());}catch(Exception error){engine.message("Biblioteca: "+Engine.reason(error));}});}
 void stop(){version.incrementAndGet();playing=false;engine.releaseFocus();engine.changed();}
 void update(){final short[] data=pcm;if(data==null)return;final int token=version.incrementAndGet(),sr=rate;final float speed=bpm/(float)Math.max(1,originalBpm);engine.worker.execute(()->{try{short[] ready=Dsp.stretch(data,sr,Math.max(.25f,Math.min(4,speed)),1);if(token==version.get()){rendered=ready;engine.output.wake();engine.changed();}}catch(Throwable error){engine.message("Drums stretch: "+Engine.reason(error));}});}
 void toggle(){if(playing){stop();return;}if(pcm==null)demo();if(!engine.acquireFocus())return;playing=true;update();engine.output.wake();engine.changed();}
 void useSelected(){if(!engine.ready()||!engine.hasPad(engine.selected))return;engine.finishPadMarking(false);engine.freezeForEdit();engine.history.begin("Chop como loop de drums");pcm=java.util.Arrays.copyOfRange(engine.source,engine.start(engine.selected)*2,engine.end(engine.selected)*2);rendered=null;rate=engine.rate;originalBpm=engine.slots.list[engine.slots.active].bpm;bpm=engine.slots.masterBpm;name="Drums · "+engine.name;update();engine.history.end();}
}
